INSERT INTO threads_generated_videos (post_id, user_id, niche, user_prompt, script, script_text, status)
VALUES ('{{ $json.post_id }}','{{ $json.user_id }}','{{ $json.niche }}','{{ $json.user_prompt.replace(/'/g,"''") }}','{{ $json.script_json.replace(/'/g,"''") }}','{{ $json.script_text.replace(/'/g,"''") }}','processing')
RETURNING id, post_id, user_id, niche, status;

UPDATE threads_generated_videos 
SET video_url = '{{ $json.response.url }}', status = 'done' 
WHERE id = {{ $('Create Video Record in DB').item.json.id }};

UPDATE threads_generated_videos 
SET status = 'approved' 
WHERE id = {{ $('Webhook: Threads Approve').item.json.body.videoId }}
RETURNING video_url;

parameters.jsCode:
const body = $input.first().json.body || $input.first().json;
const username = body.username || 'meta';
const niche = body.niche || 'general';

return [{ json: { username, niche } }];

const niche = $('Code in JavaScript1').first().json.niche || 'general';
const username = $('Code in JavaScript1').first().json.username || '';
const results = [];

for (const item of $input.all()) {
  const posts = item.json.data || item.json.threads || [];
  const list = Array.isArray(posts) ? posts : [];

  for (const thread of list) {
    const p = thread.post || thread;
    if (!p || !p.pk) continue;

    const videoVersions = p.video_versions || [];
    const hasVideo = videoVersions.length > 0;
    if (!hasVideo) continue;

    const videoUrl = videoVersions[0].url;
    const thumbnail = p.image_versions2?.candidates?.[0]?.url || null;

    results.push({
      json: {
        post_id: String(p.pk),
        post_url: `https://www.threads.net/@${p.user?.username || username}/post/${p.code}`,
        profile_url: `https://www.threads.net/@${p.user?.username || username}`,
        username: p.user?.username || username,
        text: (p.caption?.text || '').substring(0, 2000),
        like_count: parseInt(p.like_count) || 0,
        reply_count: parseInt(p.direct_reply_count) || 0,
        repost_count: parseInt(p.repost_count) || 0,
        has_video: true,
        video_url: videoUrl,
        thumbnail_url: thumbnail,
        niche: niche,
        status: 'scraped'
      }
    });
  }
}

return results.length > 0 ? results : [{ json: { skip: true, message: 'Aucune vidéo trouvée' } }];
